20	impl ContributorType {
21	    pub fn as_str(&self) -> &'static str {
22	        match self {
23	            Self::Unknown => "unknown",
24	            Self::Human => "human",
25	            Self::Ai => "ai",
26	            Self::Mixed => "mixed",
27	        }
28	    }
29	
30	    fn from_str(s: &str) -> Self {
31	        match s {
32	            "human" => Self::Human,
33	            "ai" => Self::Ai,
34	            "mixed" => Self::Mixed,
35	            _ => Self::Unknown,
36	        }
37	    }
38	}
