62	impl ProvenanceStore {
63	    pub fn open(db_path: &Path) -> Result<Self> {
64	        let conn = Connection::open(db_path)?;
65	        conn.execute_batch(
66	            "PRAGMA journal_mode=WAL;
67	             PRAGMA synchronous=NORMAL;
68	             PRAGMA busy_timeout=5000;",
69	        )?;
70	        conn.execute_batch(
71	            "CREATE TABLE IF NOT EXISTS provenance_records (
72	                id INTEGER PRIMARY KEY AUTOINCREMENT,
73	                session_id TEXT NOT NULL,
74	                timestamp_ms INTEGER NOT NULL,
75	                file_path TEXT NOT NULL,
76	                code_hash TEXT NOT NULL,
77	                model_id TEXT NOT NULL DEFAULT 'unknown',
78	                model_version TEXT NOT NULL DEFAULT '',
79	                contributor_type TEXT NOT NULL DEFAULT 'unknown',
80	                start_line INTEGER NOT NULL DEFAULT 0,
81	                end_line INTEGER NOT NULL DEFAULT 0,
82	                attestation_sig TEXT NOT NULL DEFAULT '',
83	                developer_id TEXT NOT NULL DEFAULT '',
84	                prompt_hash TEXT NOT NULL DEFAULT '',
85	                project_dir TEXT NOT NULL DEFAULT ''
86	            );
87	
88	            CREATE INDEX IF NOT EXISTS idx_provenance_file
89	                ON provenance_records(file_path);
90	            CREATE INDEX IF NOT EXISTS idx_provenance_session
91	                ON provenance_records(session_id);
92	            CREATE INDEX IF NOT EXISTS idx_provenance_timestamp
93	                ON provenance_records(timestamp_ms);
94	
95	            CREATE TABLE IF NOT EXISTS provenance_snapshots (
96	                id INTEGER PRIMARY KEY AUTOINCREMENT,
97	                session_id TEXT NOT NULL,
98	                file_path TEXT NOT NULL,
99	                content_hash TEXT NOT NULL,
100	                mtime_ns INTEGER NOT NULL,
101	                snapshot_time_ms INTEGER NOT NULL,
102	                UNIQUE(session_id, file_path)
103	            );",
104	        )?;
105	        Ok(Self { conn })
106	    }
