134	    pub fn query_by_file(&self, file_path: &str) -> Result<Vec<ProvenanceRecord>> {
135	        let mut stmt = self.conn.prepare(
136	            "SELECT id, session_id, timestamp_ms, file_path, code_hash, model_id,
137	                    model_version, contributor_type, start_line, end_line,
138	                    attestation_sig, developer_id, prompt_hash, project_dir
139	             FROM provenance_records
140	             WHERE file_path = ?1
141	             ORDER BY timestamp_ms DESC",
142	        )?;
143	        let rows = stmt
144	            .query_map(params![file_path], |row| {
145	                Ok(ProvenanceRecord {
146	                    id: Some(row.get(0)?),
147	                    session_id: row.get(1)?,
148	                    timestamp_ms: row.get(2)?,
149	                    file_path: row.get(3)?,
150	                    code_hash: row.get(4)?,
151	                    model_id: row.get(5)?,
152	                    model_version: row.get(6)?,
153	                    contributor_type: ContributorType::from_str(
154	                        &row.get::<_, String>(7)?,
155	                    ),
156	                    start_line: row.get(8)?,
157	                    end_line: row.get(9)?,
158	                    attestation_sig: row.get(10)?,
159	                    developer_id: row.get(11)?,
160	                    prompt_hash: row.get(12)?,
161	                    project_dir: row.get(13)?,
162	                })
163	            })?
164	            .collect::<Result<Vec<_>, _>>()?;
165	        Ok(rows)
166	    }
