211	    pub fn save_snapshot(
212	        &self,
213	        session_id: &str,
214	        file_path: &str,
215	        content_hash: &str,
216	        mtime_ns: i64,
217	    ) -> Result<()> {
218	        let now = now_ms();
219	        self.conn.execute(
220	            "INSERT OR REPLACE INTO provenance_snapshots
221	             (session_id, file_path, content_hash, mtime_ns, snapshot_time_ms)
222	             VALUES (?1, ?2, ?3, ?4, ?5)",
223	            params![session_id, file_path, content_hash, mtime_ns, now],
224	        )?;
225	        Ok(())
226	    }
