228	    pub fn get_snapshot(
229	        &self,
230	        session_id: &str,
231	        file_path: &str,
232	    ) -> Result<Option<(String, i64)>> {
233	        let result = self.conn.query_row(
234	            "SELECT content_hash, mtime_ns FROM provenance_snapshots
235	             WHERE session_id = ?1 AND file_path = ?2",
236	            params![session_id, file_path],
237	            |row| Ok((row.get(0)?, row.get(1)?)),
238	        );
239	        match result {
240	            Ok(v) => Ok(Some(v)),
241	            Err(rusqlite::Error::QueryReturnedNoRows) => Ok(None),
242	            Err(e) => Err(e.into()),
243	        }
244	    }
