246	    pub fn get_all_snapshots(
247	        &self,
248	        session_id: &str,
249	    ) -> Result<HashMap<String, (String, i64)>> {
250	        let mut stmt = self.conn.prepare(
251	            "SELECT file_path, content_hash, mtime_ns FROM provenance_snapshots
252	             WHERE session_id = ?1",
253	        )?;
254	        let mut map = HashMap::new();
255	        let rows = stmt.query_map(params![session_id], |row| {
256	            Ok((
257	                row.get::<_, String>(0)?,
258	                row.get::<_, String>(1)?,
259	                row.get::<_, i64>(2)?,
260	            ))
261	        })?;
262	        for row in rows {
263	            let (path, hash, mtime) = row?;
264	            map.insert(path, (hash, mtime));
265	        }
266	        Ok(map)
267	    }
