269	    pub fn cleanup(&self, retention_days: i64) -> Result<u64> {
270	        let cutoff = now_ms() - (retention_days * 86_400_000);
271	        let changes = self.conn.execute(
272	            "DELETE FROM provenance_records WHERE timestamp_ms < ?1",
273	            params![cutoff],
274	        )?;
275	        Ok(changes as u64)
276	    }
