288	pub fn extract_model_id(hook_json: Option<&serde_json::Value>) -> String {
289	    if let Ok(m) = std::env::var("CLAUDE_MODEL") {
290	        if !m.is_empty() {
291	            return m;
292	        }
293	    }
294	    if let Some(json) = hook_json {
295	        if let Some(m) = json.get("model").and_then(|v| v.as_str()) {
296	            if !m.is_empty() {
297	                return m.to_string();
298	            }
299	        }
300	    }
301	    "unknown".to_string()
302	}
