304	pub fn parse_diff_ranges(project_dir: &Path, rel_path: &str) -> Vec<(u32, u32)> {
305	    let output = Command::new("git")
306	        .args(["diff", "--unified=0", "HEAD", "--", rel_path])
307	        .current_dir(project_dir)
308	        .output();
309	
310	    let output = match output {
311	        Ok(o) if o.status.success() => o,
312	        _ => return vec![],
313	    };
314	
315	    let stdout = String::from_utf8_lossy(&output.stdout);
316	    let mut ranges = Vec::new();
317	
318	    for line in stdout.lines() {
319	        if !line.starts_with("@@") {
320	            continue;
321	        }
322	        // Parse @@ -a,b +c,d @@ format — we want the + (new file) side
323	        if let Some(plus_part) = line.split('+').nth(1) {
324	            let nums: &str = plus_part.split_whitespace().next().unwrap_or("");
325	            let parts: Vec<&str> = nums.split(',').collect();
326	            let start: u32 = parts.first().and_then(|s| s.parse().ok()).unwrap_or(1);
327	            let count: u32 = if parts.len() > 1 {
328	                parts[1].parse().unwrap_or(1)
329	            } else {
330	                1
331	            };
332	            if count > 0 {
333	                ranges.push((start, start + count - 1));
334	            }
335	        }
336	    }
337	
338	    ranges
339	}
