341	pub fn detect_changes(
342	    project_dir: &Path,
343	    session_id: &str,
344	    store: &ProvenanceStore,
345	    keypair: &attestation::KeyPair,
346	) -> Result<Vec<ProvenanceRecord>> {
347	    detect_changes_with_model(project_dir, session_id, store, keypair, None)
348	}
