350	pub fn detect_changes_with_model(
351	    project_dir: &Path,
352	    session_id: &str,
353	    store: &ProvenanceStore,
354	    keypair: &attestation::KeyPair,
355	    hook_json: Option<&serde_json::Value>,
356	) -> Result<Vec<ProvenanceRecord>> {
357	    let snapshots = store
358	        .get_all_snapshots(session_id)
359	        .unwrap_or_default();
360	
361	    if snapshots.is_empty() {
362	        return Ok(vec![]);
363	    }
364	
365	    let now = now_ms();
366	    let developer_id = whoami();
367	    let model_id = extract_model_id(hook_json);
368	    let model_version = String::new();
369	    let mut records = Vec::new();
370	
371	    for (rel_path, (old_hash, _old_mtime)) in &snapshots {
372	        let abs_path = project_dir.join(rel_path);
373	        if !abs_path.exists() {
374	            continue;
375	        }
376	
377	        let file_bytes = match std::fs::read(&abs_path) {
378	            Ok(b) => b,
379	            Err(_) => continue,
380	        };
381	
382	        let current_hash = content_hash::hash_content(&file_bytes);
383	
384	        if current_hash == *old_hash {
385	            continue;
386	        }
387	
388	        let line_count = String::from_utf8_lossy(&file_bytes).lines().count() as u32;
389	
390	        let diff_ranges = parse_diff_ranges(project_dir, rel_path);
391	        let (start_line, end_line) = if diff_ranges.is_empty() {
392	            (1, line_count)
393	        } else {
394	            let start = diff_ranges.iter().map(|(s, _)| *s).min().unwrap_or(1);
395	            let end = diff_ranges.iter().map(|(_, e)| *e).max().unwrap_or(line_count);
396	            (start, end)
397	        };
398	
399	        let prompt_hash = String::new();
400	        let sign_data = format!(
401	            "{}:{}:{}:{}:{}:{}",
402	            prompt_hash, model_id, model_version, current_hash, now, developer_id
403	        );
404	        let sig = keypair.sign(sign_data.as_bytes());
405	
406	        let rec = ProvenanceRecord {
407	            id: None,
408	            session_id: session_id.to_string(),
409	            timestamp_ms: now,
410	            file_path: rel_path.clone(),
411	            code_hash: current_hash.clone(),
412	            model_id: model_id.clone(),
413	            model_version: model_version.clone(),
414	            contributor_type: ContributorType::Ai,
415	            start_line,
416	            end_line,
417	            attestation_sig: sig,
418	            developer_id: developer_id.clone(),
419	            prompt_hash: prompt_hash.clone(),
420	            project_dir: project_dir.to_string_lossy().to_string(),
421	        };
422	
423	        records.push(rec);
424	    }
425	
426	    Ok(records)
427	}
