429	pub fn snapshot_files(
430	    project_dir: &Path,
431	    session_id: &str,
432	    store: &ProvenanceStore,
433	    files: &[String],
434	) -> Result<usize> {
435	    let mut count = 0;
436	    for rel_path in files {
437	        let abs_path = project_dir.join(rel_path);
438	        if !abs_path.exists() {
439	            continue;
440	        }
441	        let hash = match content_hash::hash_file(&abs_path) {
442	            Ok(h) => h,
443	            Err(_) => continue,
444	        };
445	        let mtime = crate::util::get_file_mtime_ns(abs_path.to_str().unwrap_or(""))
446	            .unwrap_or(0);
447	        store.save_snapshot(session_id, rel_path, &hash, mtime)?;
448	        count += 1;
449	    }
450	    Ok(count)
451	}
