63	impl PolicyConfig {
64	    pub fn load() -> Self {
65	        let candidates = config_paths();
66	        for path in &candidates {
67	            if path.exists() {
68	                if let Ok(cfg) = Self::load_from_file(path) {
69	                    return cfg;
70	                }
71	            }
72	        }
73	        Self::bundled_default()
74	    }
