76	    pub fn load_from_file(path: &Path) -> Result<Self> {
77	        let content = std::fs::read_to_string(path)?;
78	        let cfg: PolicyConfig = toml::from_str(&content)?;
79	        for rule in &cfg.limits {
80	            anyhow::ensure!(
81	                rule.max_usd >= 0.0,
82	                "max_usd must be non-negative for {}:{}",
83	                rule.scope,
84	                rule.id
85	            );
86	        }
87	        Ok(cfg)
88	    }
89	
90	    pub fn bundled_default() -> Self {
91	        Self {
92	            global: GlobalPolicy::default(),
93	            limits: vec![
94	                LimitRule {
95	                    scope: "developer".into(),
96	                    id: "*".into(),
97	                    max_usd: 500.0,
98	                    action_on_exceed: "warn".into(),
99	                },
100	            ],
101	        }
102	    }
103	}
