127	pub struct PolicyEngine {
128	    config: PolicyConfig,
129	}
130	
131	impl PolicyEngine {
132	    pub fn new(config: PolicyConfig) -> Self {
133	        Self { config }
134	    }
135	
136	    pub fn from_default() -> Self {
137	        Self::new(PolicyConfig::load())
138	    }
139	
140	    pub fn evaluate(
141	        &self,
142	        developer_id: &str,
143	        project_dir: &str,
144	        accumulated_dev: f64,
145	        accumulated_project: f64,
146	    ) -> Verdict {
147	        self.evaluate_with_team(developer_id, project_dir, accumulated_dev, accumulated_project, None, 0.0)
148	    }
149	
150	    pub fn evaluate_with_team(
151	        &self,
152	        developer_id: &str,
153	        project_dir: &str,
154	        accumulated_dev: f64,
155	        accumulated_project: f64,
156	        team_id: Option<&str>,
157	        accumulated_team: f64,
158	    ) -> Verdict {
159	        let mut worst_pct: u32 = 0;
160	        let mut worst_msg: Option<String> = None;
161	
162	        let current_team = team_id
163	            .map(|s| s.to_string())
164	            .or_else(|| std::env::var("CODEFLOW_TEAM").ok());
165	
166	        for rule in &self.config.limits {
167	            let (accumulated, scope_label) = match rule.scope.as_str() {
168	                "developer" => {
169	                    if rule.id != "*" && rule.id != developer_id {
170	                        continue;
171	                    }
172	                    (accumulated_dev, format!("developer:{}", developer_id))
173	                }
174	                "project" => {
175	                    let proj_name = project_dir
176	                        .rsplit(['/', '\\'])
177	                        .find(|s| !s.is_empty())
178	                        .unwrap_or(project_dir);
179	                    if rule.id != "*" && rule.id != proj_name {
180	                        continue;
181	                    }
182	                    (accumulated_project, format!("project:{}", proj_name))
183	                }
184	                "team" => {
185	                    let team = match &current_team {
186	                        Some(t) => t.as_str(),
187	                        None => continue,
188	                    };
189	                    if rule.id != "*" && rule.id != team {
190	                        continue;
191	                    }
192	                    (accumulated_team, format!("team:{}", team))
193	                }
194	                _ => continue,
195	            };
196	
197	            let pct = if rule.max_usd > 0.0 {
198	                (accumulated.max(0.0) / rule.max_usd * 100.0).ceil() as u32
199	            } else {
200	                100
201	            };
202	
203	            let block_pct = self.config.global.block_at_pct;
204	            let warn_pct = self.config.global.warn_at_pct;
205	
206	            if pct >= block_pct && rule.action_on_exceed == "block" {
207	                return Verdict::Block(format!(
208	                    "Budget exceeded for {} — ${:.2}/${:.2} ({}%)",
209	                    scope_label, accumulated, rule.max_usd, pct
210	                ));
211	            }
212	
213	            if pct >= warn_pct && pct > worst_pct {
214	                worst_pct = pct;
215	                worst_msg = Some(format!(
216	                    "Budget warning for {} — ${:.2}/${:.2} ({}%)",
217	                    scope_label, accumulated, rule.max_usd, pct
218	                ));
219	            }
220	        }
221	
222	        match worst_msg {
223	            Some(msg) => Verdict::Warn(msg),
224	            None => Verdict::Allow,
225	        }
226	    }
227	
228	    pub fn config(&self) -> &PolicyConfig {
229	        &self.config
230	    }
231	}
