113	fn first_word(cmd: &str) -> &str {
114	    cmd.split_whitespace().next().unwrap_or(cmd)
115	}
116	
117	fn command_complexity(command: &str) -> f64 {
118	    let cmd = command.to_lowercase();
119	    let first = first_word(&cmd);
120	
121	    let low_commands = [
122	        "git status", "git log", "git branch", "git diff --stat",
123	        "ls", "pwd", "cat", "head", "tail", "wc", "echo", "which", "whoami",
124	        "npm --version", "node --version", "cargo --version",
125	    ];
126	
127	    let high_commands = [
128	        "refactor", "architect", "design", "implement", "migrate",
129	        "review", "analyze", "debug", "optimize", "rewrite",
130	    ];
131	
132	    for lc in &low_commands {
133	        if cmd.starts_with(lc) {
134	            return -0.3;
135	        }
136	    }
137	
138	    for hc in &high_commands {
139	        if cmd.contains(hc) {
140	            return 0.3;
141	        }
142	    }
143	
144	    match first {
145	        "git" => -0.15,
146	        "ls" | "find" | "grep" | "cat" | "head" | "tail" => -0.2,
147	        "npm" | "pnpm" | "yarn" | "pip" | "cargo" => -0.1,
148	        "docker" | "kubectl" => 0.05,
149	        "python" | "node" | "go" | "rustc" => 0.1,
150	        _ => 0.0,
151	    }
152	}
153	
154	fn context_complexity(tokens: u64) -> f64 {
155	    match tokens {
156	        0..=1000 => -0.15,
157	        1001..=5000 => -0.05,
158	        5001..=20000 => 0.05,
159	        20001..=50000 => 0.15,
160	        _ => 0.25,
161	    }
162	}
163	
164	fn file_extension_complexity(extensions: &[String]) -> f64 {
165	    if extensions.is_empty() {
166	        return 0.0;
167	    }
168	
169	    let mut total = 0.0;
170	    for ext in extensions {
171	        total += match ext.as_str() {
172	            "md" | "txt" | "json" | "yaml" | "yml" | "toml" => -0.1,
173	            "html" | "css" | "scss" => -0.05,
174	            "js" | "ts" | "jsx" | "tsx" => 0.05,
175	            "py" | "rb" | "go" | "java" | "kt" => 0.1,
176	            "rs" | "cpp" | "c" | "h" => 0.15,
177	            "sql" | "graphql" | "proto" => 0.1,
178	            _ => 0.0,
179	        };
180	    }
181	
182	    (total / extensions.len() as f64).clamp(-0.2, 0.2)
183	}
184	
185	fn session_stage_complexity(event_count: u64) -> f64 {
186	    match event_count {
187	        0..=5 => -0.1,
188	        6..=20 => 0.0,
189	        21..=50 => 0.05,
190	        _ => 0.1,
191	    }
192	}
