194	pub fn classify_with_budget(
195	    input: &RoutingInput,
196	    budget_verdict: &crate::budget_policy::Verdict,
197	) -> RoutingDecision {
198	    let mut base = classify(input);
199	    match budget_verdict {
200	        crate::budget_policy::Verdict::Warn(_) if base.tier == ModelTier::Opus => {
201	            base.tier = ModelTier::Sonnet;
202	            base.reason = format!("{}, budget pressure → downgraded to sonnet", base.reason);
203	            let default_cost = ModelTier::Opus.cost_per_million_tokens();
204	            let routed_cost = base.tier.cost_per_million_tokens();
205	            base.estimated_savings_pct = if default_cost > 0.0 {
206	                (1.0 - routed_cost / default_cost) * 100.0
207	            } else {
208	                0.0
209	            };
210	        }
211	        crate::budget_policy::Verdict::Block(_) => {
212	            base.tier = ModelTier::Haiku;
213	            base.reason = format!("{}, budget blocked → forced haiku", base.reason);
214	            let default_cost = ModelTier::Opus.cost_per_million_tokens();
215	            let routed_cost = base.tier.cost_per_million_tokens();
216	            base.estimated_savings_pct = if default_cost > 0.0 {
217	                (1.0 - routed_cost / default_cost) * 100.0
218	            } else {
219	                0.0
220	            };
221	        }
222	        _ => {}
223	    }
224	    base
225	}
