227	pub fn extensions_from_paths(paths: &[&str]) -> Vec<String> {
228	    let mut exts: Vec<String> = paths
229	        .iter()
230	        .filter_map(|p| Path::new(p).extension())
231	        .filter_map(|e| e.to_str())
232	        .map(|e| e.to_lowercase())
233	        .collect();
234	    exts.sort();
235	    exts.dedup();
236	    exts
237	}
