135	    if json {
136	        println!("{}", serde_json::to_string_pretty(&groups)?);
137	        return Ok(());
138	    }
139	
140	    if groups.is_empty() {
141	        println!("No spending history for the last {} days.", period_d);
142	        return Ok(());
143	    }
144	
145	    println!("\n  Spending History (last {} days)\n", period_d);
146	    println!(
147	        "  {:<12} {:>10} {:>12} {:>12} {:>6}",
148	        "Date", "Cost ($)", "Input Tok", "Output Tok", "Count"
149	    );
150	    println!("  {}", "─".repeat(56));
151	
152	    for g in &groups {
153	        println!(
154	            "  {:<12} {:>10.2} {:>12} {:>12} {:>6}",
155	            g.key,
156	            g.cost_usd,
157	            format_tokens(g.input_tokens),
158	            format_tokens(g.output_tokens),
159	            g.record_count,
160	        );
161	    }
162	
163	    let total: f64 = groups.iter().map(|g| g.cost_usd).sum();
164	    println!("  {}", "─".repeat(56));
165	    println!("  {:<12} {:>10.2}", "TOTAL", total);
166	    println!();
167	
168	    Ok(())
169	}
