171	pub fn webhook_alert_body(
172	    verdict: &Verdict,
173	    policy: &LimitRule,
174	    spent: f64,
175	) -> serde_json::Value {
176	    let action = match verdict {
177	        Verdict::Warn(_) => "warn",
178	        Verdict::Block(_) => "block",
179	        Verdict::Allow => "allow",
180	    };
181	    serde_json::json!({
182	        "policy_id": format!("{}:{}", policy.scope, policy.id),
183	        "action": action,
184	        "spent_usd": spent,
185	        "limit_usd": policy.max_usd,
186	        "percentage": if policy.max_usd > 0.0 { spent / policy.max_usd * 100.0 } else { 100.0 },
187	    })
188	}
